import React, { useState, useEffect, useCallback } from 'react';
import { fetchCurrentExchangeRate } from './services/geminiService';
import { ConversionInput } from './components/ConversionInput';
import { Footer } from './components/Footer';

// Constants
const LITRES_PER_GALLON = 3.78541;

const App: React.FC = () => {
  const [exchangeRate, setExchangeRate] = useState<number | null>(null);
  const [sources, setSources] = useState<string[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  // State for inputs
  const [usdPrice, setUsdPrice] = useState<string>("");
  const [cadPrice, setCadPrice] = useState<string>("");
  const [lastEdited, setLastEdited] = useState<'USD' | 'CAD' | null>(null);

  // Initialize data
  useEffect(() => {
    const initData = async () => {
      setLoading(true);
      const data = await fetchCurrentExchangeRate();
      setExchangeRate(data.rate);
      setSources(data.sources);
      setLoading(false);
    };
    initData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Recalculate when rate changes or values change
  const convertUsdToCad = useCallback((usd: number, rate: number) => {
    // Formula: (USD/Gal / 3.78541) * Rate = CAD/L
    return (usd / LITRES_PER_GALLON) * rate;
  }, []);

  const convertCadToUsd = useCallback((cad: number, rate: number) => {
    // Formula: (CAD/L * 3.78541) / Rate = USD/Gal
    return (cad * LITRES_PER_GALLON) / rate;
  }, []);

  const handleUsdChange = (val: string) => {
    setUsdPrice(val);
    setLastEdited('USD');
    if (val === '' || !exchangeRate) {
      setCadPrice('');
      return;
    }
    const num = parseFloat(val);
    if (!isNaN(num)) {
      const converted = convertUsdToCad(num, exchangeRate);
      setCadPrice(converted.toFixed(3)); // Gas usually 3 decimal places
    }
  };

  const handleCadChange = (val: string) => {
    setCadPrice(val);
    setLastEdited('CAD');
    if (val === '' || !exchangeRate) {
      setUsdPrice('');
      return;
    }
    const num = parseFloat(val);
    if (!isNaN(num)) {
      const converted = convertCadToUsd(num, exchangeRate);
      setUsdPrice(converted.toFixed(3));
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-blue-50 to-red-50 flex items-center justify-center p-4">
      <div className="w-full max-w-md">

        {/* Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center p-3 bg-white rounded-2xl shadow-md mb-4">
            <span className="text-3xl mr-2">⛽</span>
            <span className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-red-600">
              CanAm Gas
            </span>
          </div>
          <h1 className="text-gray-600 font-medium">Cross-Border Price Converter</h1>
        </div>

        {/* Card */}
        <div className="bg-white/60 backdrop-blur-xl rounded-3xl shadow-xl border border-white p-6 md:p-8">

          {loading ? (
            <div className="flex flex-col items-center justify-center py-12 space-y-4">
              <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
              <p className="text-sm text-gray-500 animate-pulse">Fetching live rates via Gemini...</p>
            </div>
          ) : (
            <div className="space-y-6">

              {/* USD Input */}
              <ConversionInput
                label="United States"
                subLabel="USD per Gallon"
                icon="🇺🇸"
                prefix="$"
                value={usdPrice}
                onChange={handleUsdChange}
                active={lastEdited === 'USD'}
              />

              {/* Arrow Indicator */}
              <div className="relative h-4 flex items-center justify-center">
                <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-gray-300"></div>
                </div>
                <div className="relative bg-white px-2 text-gray-400">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4" />
                  </svg>
                </div>
              </div>

              {/* CAD Input */}
              <ConversionInput
                label="Canada"
                subLabel="CAD per Litre"
                icon="🇨🇦"
                prefix="$"
                value={cadPrice}
                onChange={handleCadChange}
                active={lastEdited === 'CAD'}
              />

              {/* Quick Summary Badge (e.g. Break-even) */}
              {usdPrice && cadPrice && exchangeRate && (
                 <div className="mt-4 p-3 bg-blue-50 rounded-lg border border-blue-100 text-center">
                   <p className="text-sm text-blue-800 font-medium">
                     Break-even Calculation
                   </p>
                   <p className="text-xs text-blue-600 mt-1">
                     ${usdPrice} USD/gal is roughly equivalent to <span className="font-bold">${cadPrice} CAD/L</span>
                   </p>
                 </div>
              )}

            </div>
          )}
        </div>

        {/* Footer Info */}
        {!loading && exchangeRate && (
          <Footer rate={exchangeRate} sources={sources} />
        )}

      </div>
    </div>
  );
};

export default App;

